pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // 1. restrict caller to not be the current owner (the only cases where the bug can manifest)
        vm.assume(caller != c.owner());
        // 2. record the current owner before the call
        address prevOwner = c.owner();
        // 3. call as the non-owner caller
        vm.prank(caller);
        c.transferOwnership(newOwner);
        // 4. assert that the owner did NOT change (reference behavior)
        assertTrue(c.owner() == prevOwner);
    }
}

