// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // Set up the contract with a known owner and a non-owner actor.
        // The owner is the test contract itself (msg.sender in setUp -> deployer).
        // The actor is a fuzzed address different from the owner.
        vm.assume(actor != address(this));

        // Transfer ownership to a separate address so we can test both owner and non-owner calls.
        // Use a fresh address as the new owner.
        address newOwner = address(uint160(uint256(keccak256(abi.encode(actor)))));
        vm.assume(newOwner != address(0) && newOwner != actor && newOwner != address(this));
        c.transferOwnership(newOwner);

        // Test 1: actor (non-owner) calls owned().
        // Reference C: must revert (owned protected by onlyOwner, actor != owner).
        // Mutant M: must succeed (require(msg.sender != owner) passes for non-owners).
        bool actorSuccess;
        vm.prank(actor);
        try c.owned() { actorSuccess = true; } catch { actorSuccess = false; }

        // Test 2: owner calls owned().
        // Reference C: must succeed.
        // Mutant M: must revert.
        bool ownerSuccess;
        vm.prank(newOwner);
        try c.owned() { ownerSuccess = true; } catch { ownerSuccess = false; }

        // The rule: owned() succeeds when called by the owner AND fails when called by any non-owner.
        // The invariant is: `ownerSuccess == true && actorSuccess == false`.
        assertTrue(ownerSuccess && !actorSuccess);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // 1. restrict to valid owner candidate (non-zero for practical purposes)
        vm.assume(newOwner != address(0));
        // set the fuzzer as the initial owner
        c.transferOwnership(address(this));
        // 2. initiate ownership transfer as current owner
        c.transferOwnership(newOwner);
        // 3. assert that ownership was correctly transferred to newOwner
        assertTrue(c.owner() == newOwner);
    }
}
